#include <stdio.h>
#include <stdlib.h>
#include <string.h>

char *repeat(const char *s, int k, char sep) {
    size_t len = strlen(s);
    size_t total = (size_t)k * len + (k > 0 ? (size_t)k - 1 : 0);
    char *out = malloc(total + 1);
    if (out == NULL) {
        return NULL;
    }
    char *pos = out;
    for (int i = 0; i < k; i++) {
        if (i > 0) {
            *pos++ = sep;
        }
        memcpy(pos, s, len);
        pos += len;
    }
    *pos = '\0';
    return out;
}

int main(void) {
    char s[51];
    int k;
    scanf("%50s %d", s, &k);
    char *r = repeat(s, k, '-');
    if (r == NULL) {
        return 1;
    }
    printf("[%s]\n", r);
    free(r);
    return 0;
}

