#include <stdio.h>
#include <stdlib.h>

struct Task {
    char title[31];
    int priority;
    int done;
};

struct Task *task_create(const char *title, int priority) {
    struct Task *t = malloc(sizeof *t);
    if (t == NULL) {
        return NULL;
    }
    snprintf(t->title, sizeof t->title, "%s", title);
    t->priority = priority;
    t->done = 0;
    return t;
}

int main(void) {
    int n;
    scanf("%d", &n);
    struct Task *tasks[50];
    for (int i = 0; i < n; i++) {
        int priority;
        char title[31];
        scanf("%d %30s", &priority, title);
        tasks[i] = task_create(title, priority);
        if (tasks[i] == NULL) {
            for (int k = 0; k < i; k++) {
                free(tasks[k]);
            }
            return 1;
        }
    }
    int id;
    while (scanf("%d", &id) == 1 && id != -1) {
        tasks[id]->done = 1;
    }
    for (int i = 1; i < n; i++) {
        struct Task *current = tasks[i];
        int j = i - 1;
        while (j >= 0 && tasks[j]->priority < current->priority) {
            tasks[j + 1] = tasks[j];
            j--;
        }
        tasks[j + 1] = current;
    }
    int printed = 0;
    for (int i = 0; i < n; i++) {
        if (!tasks[i]->done) {
            printf("%d %s\n", tasks[i]->priority, tasks[i]->title);
            printed++;
        }
    }
    if (printed == 0) {
        printf("all done\n");
    }
    for (int i = 0; i < n; i++) {
        free(tasks[i]);
    }
    return 0;
}

